					"#009ceb",
					"#7b56db"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "Occupancy"
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Spaces × DNAC — occupancy (columns) + RSSI overlay",
			"type": "splunk.column"
		}
	},
	"dataSources": {
		"ds_act_compare_chart": {
			"name": "Baseline week vs Exercise window - by metric",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" (eventType=\"DEVICE_COUNT\" OR eventType=\"DEVICE_ASSOCIATION\")\n| addinfo\n| eval split_time=info_min_time+((info_max_time-info_min_time)/2)\n| eval phase=if(_time<split_time, \"Baseline (first half)\", \"Exercise (second half)\")\n| eval people=if(eventType=\"DEVICE_COUNT\", coalesce('deviceCounts.userCount', 'deviceCounts.associatedCount', 'deviceCounts.deviceCount'), null())\n| eval assoc_mac=if(eventType=\"DEVICE_ASSOCIATION\" AND 'deviceAssociation.event'=\"ASSOCIATE\", lower('deviceAssociation.device.macAddress'), null())\n| eval assoc_user=if(eventType=\"DEVICE_ASSOCIATION\" AND 'deviceAssociation.event'=\"ASSOCIATE\", coalesce('deviceAssociation.userName', 'deviceAssociation.username', 'deviceAssociation.user.name'), null())\n| bin _time span=1h\n| stats max(people) as people, dc(assoc_user) as unique_users, dc(assoc_mac) as unique_devices by phase _time\n| eval unique_users=if(unique_users>0, unique_users, unique_devices)\n| stats avg(people) as \"People in buildings (avg/hr)\", avg(unique_users) as \"Unique users (avg/hr)\", avg(unique_devices) as \"Unique devices (avg/hr)\" by phase\n| untable phase metric value\n| eval value=round(value, 2)\n| xyseries metric phase value",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_act_compare_kpi": {
			"name": "Spaces baseline x exercise - surge multiplier",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\"\n| addinfo\n| eval split_time=info_min_time+((info_max_time-info_min_time)/2)\n| eval people=coalesce('deviceCounts.userCount', 'deviceCounts.associatedCount', 'deviceCounts.deviceCount')\n| where isnotnull(people) AND people>0\n| eval phase=if(_time<split_time, \"baseline\", \"exercise\")\n| bin _time span=1h\n| stats max(people) as people by phase _time\n| stats avg(eval(if(phase=\"baseline\", people, null()))) as baseline, avg(eval(if(phase=\"exercise\", people, null()))) as exercise\n| eval multiplier=if(isnotnull(baseline) AND baseline>0 AND isnotnull(exercise), round(exercise/baseline, 2), 0)\n| fields multiplier",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_activation_annotation": {
			"name": "2026 key dates annotations",
			"options": {
				"query": "| makeresults count=7\n| streamstats count as id\n| eval _time=case(id=1, strptime(\"2026-04-01 09:00:00\", \"%Y-%m-%d %H:%M:%S\"),\n id=2, strptime(\"2026-04-10 09:00:00\", \"%Y-%m-%d %H:%M:%S\"),\n id=3, strptime(\"2026-04-11 09:00:00\", \"%Y-%m-%d %H:%M:%S\"),\n id=4, strptime(\"2026-04-13 08:00:00\", \"%Y-%m-%d %H:%M:%S\"),\n id=5, strptime(\"2026-04-14 08:00:00\", \"%Y-%m-%d %H:%M:%S\"),\n id=6, strptime(\"2026-04-15 08:00:00\", \"%Y-%m-%d %H:%M:%S\"),\n id=7, strptime(\"2026-04-15 18:00:00\", \"%Y-%m-%d %H:%M:%S\")),\n label=case(id=1, \"Reg / Sponsor deadline\",\n id=2, \"FACHC Refund deadline\",\n id=3, \"Hurricane Prep Workshop\",\n id=4, \"Op Florida Ready - Day 1\",\n id=5, \"Op Florida Ready - Day 2\",\n id=6, \"Op Florida Ready - Day 3\",\n id=7, \"Op Florida Ready - Close\"),\n color=case(id<=3, \"#9E9E9E\",\n id>=4 AND id<=6, \"#D64550\",\n id=7, \"#6EBE4A\")\n| table _time label color",
				"queryParameters": {
					"earliest": "01/01/2024:00:00:00",
					"latest": "12/31/2030:23:59:59"
				}
			},
			"type": "ds.search"
		},
		"ds_activation_env": {
			"name": "Webex - temperature and humidity during activation",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\"\n| eval temp='webexTelemetryUpdate.telemetries{}.ambientTemp',\n humidity='webexTelemetryUpdate.telemetries{}.relativeHumidity',\n device='webexTelemetryUpdate.deviceInfo.serialNumber'\n| where isnotnull(temp) AND isnotnull(humidity)\n| eval temp_f=round(temp*9/5+32, 2)\n| stats avg(temp_f) as \"Avg Temp °F\", avg(humidity) as \"Avg Humidity %\", min(temp_f) as \"Min Temp °F\", max(temp_f) as \"Max Temp °F\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_activation_kpi_capacity": {
			"name": "Peak capacity Perc",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR \n| eval users='deviceCounts.userCount',\n    associated='deviceCounts.associatedCount',\n    devices='deviceCounts.deviceCount',\n    pct='deviceCounts.estimatedCapacityPercentage',\n    floor='deviceCounts.location.name',\n    building='deviceCounts.location.parent.name',\n    city='deviceCounts.location.parent.parent.name' \n| stats max(pct) as \"Peak Capacity %\" \n| eval \"Peak Capacity %\"=round('Peak Capacity %', 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_activation_kpi_peak": {
			"name": "Peak users",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'\n| bin _time span=1h \n| stats max(users) as peak by _time, floor\n| stats max(peak) as \"Peak Users\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_activation_kpi_ssid": {
			"name": "WiFi associations",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"\n| eval mac='deviceAssociation.device.macAddress',\n ssid='deviceAssociation.ssid'\n| stats count as \"Total Associations\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
