		"ds_activation_surge": {
			"name": "Spaces occupancy surge Op Florida Ready annotations",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR \n| eval users=coalesce('deviceCounts.userCount', 'deviceCounts.associatedCount', 'deviceCounts.deviceCount'),\n    floor='deviceCounts.location.name' \n| where isnotnull(users) \n| bin _time span=1h \n| stats max(users) as users by _time, floor \n| stats sum(users) as Occupancy by _time \n| eval Occupancy=round(Occupancy, 2) \n| fields _time Occupancy",
				"queryParameters": {
