		"ds_ap_health_dist": {
			"name": "AP health distribution by tier",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\"\n| stats latest(OverallHealth) as health by DeviceName\n| eval tier=case(health>=9, \"Excellent (9-10)\",\n health>=7, \"Good (7-8)\",\n health>=5, \"Fair (5-6)\",\n health>=1, \"Poor (1-4)\",\n 1=1, \"No Data (0)\")\n| stats count by tier",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ap_health_table": {
			"name": "AP health detail table",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\"\n| stats latest(OverallHealth) as Health,\n latest(CPUUtilization) as \"CPU %\",\n latest(MemoryUtilization) as \"Mem %\",\n latest(IssueCount) as Issues,\n latest(ClientCountGhz24) as \"2.4 GHz Clients\",\n latest(ClientCountGhz50) as \"5 GHz Clients\",\n latest(AirQualityHealthGhz24) as \"Air Quality 2.4\",\n latest(AirQualityHealthGhz50) as \"Air Quality 5\",\n latest(InterferenceHealthGhz24) as \"Interference 2.4\",\n latest(InterferenceHealthGhz50) as \"Interference 5\",\n latest(Site) as Site by DeviceName\n| eval \"Total Clients\"='2.4 GHz Clients'+'5 GHz Clients',\n \"CPU %\"=round('CPU %', 2),\n \"Mem %\"=round('Mem %', 2)\n| sort - \"Total Clients\"\n| rename DeviceName as \"Access Point\"\n| table \"Access Point\", Site, Health, \"CPU %\", \"Mem %\", Issues, \"Total Clients\", \"2.4 GHz Clients\", \"5 GHz Clients\", \"Air Quality 2.4\", \"Air Quality 5\" ",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_band_distribution": {
			"name": "Client band distribution",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" connectionStatus=\"connected\"\n| eval band='connection.band'\n| where isnotnull(band)\n| stats count by band",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_capacity_gauge_first": {
			"name": "Highest capacity floor period peak",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'\n| where isnotnull(pct) | stats latest(pct) as \"Capacity %\"\n| eval \"Capacity %\"=round('Capacity %', 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_capacity_gauge_second": {
			"name": "Second highest capacity floor period peak",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'\n| where isnotnull(pct) | stats latest(pct) as \"Capacity %\"\n| eval \"Capacity %\"=round('Capacity %', 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_capacity_predict": {
			"name": "Occupancy forecast 24-hour prediction",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR \n| eval users='deviceCounts.userCount',\n    associated='deviceCounts.associatedCount',\n    devices='deviceCounts.deviceCount',\n    pct='deviceCounts.estimatedCapacityPercentage',\n    floor='deviceCounts.location.name',\n    building='deviceCounts.location.parent.name',\n    city='deviceCounts.location.parent.parent.name' \n| bin _time span=1h \n| stats max(users) as users by _time, floor \n| stats sum(users) as users by _time \n| timechart span=1h max(eval(round(users, 2))) as users \n| predict users as predicted future_timespan=24 \n| rename \"upper95(prediction(users))\" as upper95,\n    \"lower95(prediction(users))\" as lower95 \n| eval users=round(users, 2),\n    predicted=round(predicted, 2),\n    upper95=round(upper95, 2),\n    lower95=round(lower95, 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_capacity_trend": {
			"name": "Capacity Perc by floor over time",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR \n| eval users='deviceCounts.userCount',\n    associated='deviceCounts.associatedCount',\n    devices='deviceCounts.deviceCount',\n    pct='deviceCounts.estimatedCapacityPercentage',\n    floor='deviceCounts.location.name',\n    building='deviceCounts.location.parent.name',\n    city='deviceCounts.location.parent.parent.name' \n| where isnotnull(pct) \n| bin _time span=1h \n| stats max(pct) as pct by _time, floor, building \n| timechart span=1h useother=t max(eval(round(pct, 2))) as \"Capacity %\" by floor where max in top10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_client_health_by_site": {
			"name": "Client health score by site over time",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" connectionStatus=\"connected\"\n| eval siteHierarchy=`dnac_site_normalize(siteHierarchy)`,\n health='health.overallScore'\n| where siteHierarchy!=\"\" AND isnotnull(health) AND health>0\n| bin _time span=1h\n| stats avg(health) as health by _time, siteHierarchy\n| timechart span=1h useother=t avg(eval(round(health, 2))) as \"Client Health\" by siteHierarchy where max in top10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_convergence_annotations": {
			"name": "Op Florida Ready exercise annotations Convergence",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\"\n| dedup IssueID\n| eval label=\"DNAC: \".IssueSpecificName.\" - \".SiteName,\n color=\"#D64550\"\n| table _time label color\n| sort - _time\n| head 20",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_convergence_health": {
			"name": "Convergence health scores",
			"options": {
				"query": "`index_catalyst` (sourcetype=\"cisco:dnac:networkhealth\" category=\"All\") OR (sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\")\n| eval metric=case(sourcetype=\"cisco:dnac:networkhealth\", \"network_health\",\n sourcetype=\"cisco:dnac:clienthealth\", \"client_health\"),\n value=case(sourcetype=\"cisco:dnac:networkhealth\", healthScore,\n sourcetype=\"cisco:dnac:clienthealth\", scoreValue)\n| bin _time span=1h \n| stats latest(eval(if(metric=\"network_health\", value, null()))) as \"Network Health\",\n latest(eval(if(metric=\"client_health\", value, null()))) as \"Client Health\" by _time\n| eval \"Network Health\"=round('Network Health', 2),\n \"Client Health\"=round('Client Health', 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_convergence_occupancy": {
			"name": "Spaces x DNAC - occupancy and DNAC issues and date annotations",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'\n| where isnotnull(users)\n| timechart max(users) as Occupancy\n| eval Occupancy=round(Occupancy, 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dwell_distribution": {
			"name": "Dwell time distribution",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" \n| rename devicePresence.device.macAddress as mac, deviceAssociation.event as event \n| streamstats current=f last(event) as prev_event, last(_time) as prev_time by mac \n| where event=\"DISASSOCIATE\" AND prev_event=\"ASSOCIATE\" \n| eval dwell_min=round((_time-prev_time)/60, 2) \n| eval bucket=case(dwell_min<30, \"< 30 min\",\n    dwell_min<60, \"30-60 min\",\n    dwell_min<120, \"1-2 hrs\",\n    dwell_min<240, \"2-4 hrs\",\n    dwell_min<480, \"4-8 hrs\",\n    1=1, \"8+ hrs\") \n| stats count by bucket \n| rename bucket as \"Dwell Time\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_env_annotation": {
			"name": "Op Florida Ready exercise annotations Environmental",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\"\n| eval temp='webexTelemetryUpdate.telemetries{}.ambientTemp',\n humidity='webexTelemetryUpdate.telemetries{}.relativeHumidity',\n device='webexTelemetryUpdate.deviceInfo.serialNumber'\n| where isnotnull(temp) AND isnotnull(humidity)\n| eval temp_f=round(temp*9/5+32, 2)\n| where temp_f >= 78 OR humidity >= 65\n| eval label=case(temp_f>=78, \"Heat \".round(temp_f, 0).\"°F\", humidity>=65, \"Humidity \".round(humidity, 0).\"%\")\n| dedup _time, label\n| sort - _time\n| head 10\n| table _time label",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
