		"ds_env_kpi_temp": {
			"name": "Avg temperature",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\"\n| eval temp='webexTelemetryUpdate.telemetries{}.ambientTemp',\n humidity='webexTelemetryUpdate.telemetries{}.relativeHumidity',\n device='webexTelemetryUpdate.deviceInfo.serialNumber'\n| where isnotnull(temp)\n| eval temp_f=round(temp*9/5+32, 2)\n| timechart avg(temp_f) as \"Temp °F\"\n| eval \"Temp °F\"=round('Temp °F', 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_env_occupancy_overlay": {
			"name": "Occupancy vs temperature overlay",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" (eventType=\"DEVICE_COUNT\" OR eventType=\"WEBEX_TELEMETRY\")\n| eval users=if(eventType=\"DEVICE_COUNT\", 'deviceCounts.userCount', null()),\n temp=if(eventType=\"WEBEX_TELEMETRY\", 'webexTelemetryUpdate.telemetries{}.ambientTemp', null())\n| where isnotnull(users) OR isnotnull(temp)\n| eval temp_f=if(isnotnull(temp), round(temp*9/5+32, 2), null())\n| bin _time span=1h \n| stats max(users) as Users, avg(temp_f) as temp_avg by _time\n| eval Users=round(Users, 2),\n \"Temperature (F)\"=round(temp_avg, 2)\n| fields _time Users \"Temperature (F)\" ",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_env_scatter": {
			"name": "Temperature vs users scatter",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" (eventType=\"DEVICE_COUNT\" OR eventType=\"WEBEX_TELEMETRY\")\n| eval users=if(eventType=\"DEVICE_COUNT\", 'deviceCounts.userCount', null()),\n temp=if(eventType=\"WEBEX_TELEMETRY\", 'webexTelemetryUpdate.telemetries{}.ambientTemp', null())\n| where isnotnull(users) OR isnotnull(temp)\n| eval temp_f=if(isnotnull(temp), round(temp*9/5+32, 2), null())\n| bin _time span=1h \n| stats max(users) as users, avg(temp_f) as temp_f by _time\n| where isnotnull(users) AND isnotnull(temp_f)\n| eval users=round(users, 2), temp_f=round(temp_f, 2)\n| table users temp_f",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_env_summary": {
			"name": "Current sensor readings",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\"\n| eval temp='webexTelemetryUpdate.telemetries{}.ambientTemp',\n humidity='webexTelemetryUpdate.telemetries{}.relativeHumidity',\n device='webexTelemetryUpdate.deviceInfo.serialNumber'\n| where isnotnull(temp) AND isnotnull(humidity)\n| eval temp_f=round(temp*9/5+32, 2)\n| stats avg(temp_f) as avg_temp, avg(humidity) as avg_humidity, count\n| eval comfort=case(avg_temp>=68 AND avg_temp<=76 AND avg_humidity>=30 AND avg_humidity<=60, \"✓ Optimal\",\n avg_temp>76 OR avg_humidity>60, \"⚠ Warm/Humid\",\n 1=1, \"✗ Cool/Dry\")\n| eval avg_temp=round(avg_temp, 1), avg_humidity=round(avg_humidity, 1)\n| table comfort, avg_temp, avg_humidity, count\n| rename comfort as \"Comfort\", avg_temp as \"Avg Temp °F\", avg_humidity as \"Avg Humidity %\", count as \"Readings\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_humidity_trend": {
			"name": "Webex sensors - humidity by floor and exercise annotations",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\"\n| eval temp='webexTelemetryUpdate.telemetries{}.ambientTemp',\n humidity='webexTelemetryUpdate.telemetries{}.relativeHumidity',\n device='webexTelemetryUpdate.deviceInfo.serialNumber'\n| where isnotnull(humidity) AND isnotnull(device)\n| timechart avg(humidity) as \"Humidity %\" by device limit=10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
