		"ds_inter_campus": {
			"name": "KPI Inter-campus travelers",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| eval mac='devicePresence.macAddress'\n| eval bldg_self=if(mvfind('devicePresence.location.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.name', null())\n| eval bldg_parent=if(mvfind('devicePresence.location.parent.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.parent.name', null())\n| eval bldg_grand=if(mvfind('devicePresence.location.parent.parent.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.parent.parent.name', null())\n| eval building=coalesce(bldg_self, bldg_parent, bldg_grand)\n| where isnotnull(mac) AND mac!=\"\" AND isnotnull(building) AND building!=\"\"\n| stats dc(building) as buildings by mac\n| where buildings>1\n| stats count as \"Inter-Campus Travelers\" ",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_issues_by_site": {
			"name": "DNAC - issues by site",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\"\n| dedup IssueID\n| stats count as Issues by SiteName\n| sort - Issues\n| rename SiteName as Site",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_issues_with_occupancy": {
			"name": "Issues by severity and Occupancy overlay",
			"options": {
				"query": "`index_catalyst` OR `index_spaces` (sourcetype=\"cisco:dnac:issue\") OR (sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR)\n| eval metric=case(sourcetype=\"cisco:dnac:issue\", \"issue\",\n sourcetype=\"cisco:spaces:firehose\", \"occupancy\"),\n severity=if(metric=\"issue\", IssueSpecificSeverity, null()),\n users=if(metric=\"occupancy\", 'deviceCounts.userCount', null())\n| bin _time span=1h \n| stats dc(eval(if(metric=\"issue\" AND severity=\"HIGH\", IssueID, null()))) as High,\n dc(eval(if(metric=\"issue\" AND severity=\"MEDIUM\", IssueID, null()))) as Medium,\n dc(eval(if(metric=\"issue\" AND severity=\"LOW\", IssueID, null()))) as Low,\n max(users) as Occupancy by _time\n| eval Occupancy=round(Occupancy, 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_avg_week": {
			"name": "Avg users period",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'\n| bin _time span=1h \n| stats max(users) as peak by _time, floor\n| stats avg(peak) as \"Avg Concurrent Users\"\n| eval \"Avg Concurrent Users\"=round('Avg Concurrent Users', 0)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_peak_today": {
			"name": "Peak users today",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'\n| bin _time span=1h \n| stats max(users) as peak by _time, floor\n| stats max(peak) as \"Peak Concurrent Users\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_repeat_pct": {
			"name": "Repeat visitors",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"\n| eval mac='deviceAssociation.device.macAddress',\n ssid='deviceAssociation.ssid'\n| eval day=strftime(_time, \"%Y-%m-%d\")\n| where isnotnull(mac) AND mac!=\"\"\n| stats dc(day) as days_seen by mac\n| eval is_repeat=if(days_seen>=2, 1, 0)\n| stats count as total, sum(is_repeat) as repeat\n| eval \"Repeat %\"=round(repeat/total*100, 2)\n| table \"Repeat %\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
