		"ds_occupancy_vs_health": {
			"name": "Scatter Occupancy vs Client Health",
			"options": {
				"query": "`index_catalyst` OR `index_spaces` (sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\") OR (sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR)\n| eval metric=case(sourcetype=\"cisco:dnac:clienthealth\", \"health\",\n sourcetype=\"cisco:spaces:firehose\", \"occupancy\"),\n value=case(sourcetype=\"cisco:dnac:clienthealth\", scoreValue,\n sourcetype=\"cisco:spaces:firehose\", 'deviceCounts.userCount')\n| bin _time span=1h \n| stats max(eval(if(metric=\"occupancy\", value, null()))) as occupancy,\n latest(eval(if(metric=\"health\", value, null()))) as client_health by _time\n| where isnotnull(occupancy) AND isnotnull(client_health)\n| eval occupancy=round(occupancy, 2),\n client_health=round(client_health, 2)\n| table occupancy client_health",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_onboarding_vs_occupancy": {
			"name": "Onboarding time vs Occupancy",
			"options": {
				"query": "`index_catalyst` OR `index_spaces` (sourcetype=\"cisco:dnac:client\") OR (sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR)\n| eval metric=case(sourcetype=\"cisco:dnac:client\", \"onboard\",\n sourcetype=\"cisco:spaces:firehose\", \"occupancy\"),\n onboard_ms=if(metric=\"onboard\", 'onboarding.avgRunDuration', null()),\n users=if(metric=\"occupancy\", 'deviceCounts.userCount', null())\n| bin _time span=1h \n| stats max(users) as Occupancy, avg(onboard_ms) as onboard_avg by _time\n| where isnotnull(Occupancy)\n| eval Occupancy=round(Occupancy, 2),\n \"Avg Onboarding (ms)\"=round(onboard_avg, 2)\n| fields _time Occupancy \"Avg Onboarding (ms)\" ",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_kpi_ghost": {
			"name": "Ghost rooms",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM\n| rename \"spaceOccupancy.space.name\" as room,\n \"spaceOccupancy.space.capacity\" as capacity,\n \"spaceOccupancy.peakPeopleCount\" as people,\n \"spaceOccupancy.peoplePresence\" as presence,\n \"spaceOccupancy.location.name\" as floor,\n \"spaceOccupancy.location.parent.name\" as building\n| eval occupied=if(presence=\"true\" OR people>0, 1, 0)\n| stats sum(occupied) as occupied_count, count by room\n| eval ghost_pct=round((1 - occupied_count/count)*100, 2)\n| where ghost_pct >= 80\n| stats count as \"Ghost Rooms\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_kpi_hot": {
			"name": "Hot rooms",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM\n| rename \"spaceOccupancy.space.name\" as room,\n \"spaceOccupancy.space.capacity\" as capacity,\n \"spaceOccupancy.peakPeopleCount\" as people,\n \"spaceOccupancy.peoplePresence\" as presence,\n \"spaceOccupancy.location.name\" as floor,\n \"spaceOccupancy.location.parent.name\" as building\n| stats avg(people) as avg_people by room, capacity\n| eval util=if(capacity>0, avg_people/capacity, 0)\n| where util >= 0.5\n| stats count as \"Hot Rooms\"",
				"queryParameters": {
