			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM\n| rename \"spaceOccupancy.space.name\" as room,\n \"spaceOccupancy.space.capacity\" as capacity,\n \"spaceOccupancy.peakPeopleCount\" as people,\n \"spaceOccupancy.peoplePresence\" as presence,\n \"spaceOccupancy.location.name\" as floor,\n \"spaceOccupancy.location.parent.name\" as building\n| stats dc(room) as \"Total Rooms\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_punchcard": {
			"name": "Occupancy by day and hour",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM\n| rename \"spaceOccupancy.space.name\" as room,\n \"spaceOccupancy.space.capacity\" as capacity,\n \"spaceOccupancy.peakPeopleCount\" as people,\n \"spaceOccupancy.peoplePresence\" as presence,\n \"spaceOccupancy.location.name\" as floor,\n \"spaceOccupancy.location.parent.name\" as building\n| eval hour=strftime(_time, \"%H\"),\n dow=strftime(_time, \"%A\"),\n occupied=if(presence=\"true\" OR people>0, 1, 0)\n| stats avg(occupied) as occupancies by dow, hour\n| eval occupancies=round(occupancies*100, 2)\n| sort dow, hour",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_tier_pie": {
			"name": "Rooms by utilization tier",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM\n| rename \"spaceOccupancy.space.name\" as room,\n \"spaceOccupancy.space.capacity\" as capacity,\n \"spaceOccupancy.peakPeopleCount\" as people,\n \"spaceOccupancy.peoplePresence\" as presence,\n \"spaceOccupancy.location.name\" as floor,\n \"spaceOccupancy.location.parent.name\" as building\n| stats avg(people) as avg_people by room, capacity\n| eval util=if(capacity>0, avg_people/capacity, 0)\n| eval tier=case(util>=0.8, \"Hot (>=80%)\", util>=0.4, \"Active (40-80%)\", util>0, \"Idle (<40%)\", 1=1, \"Empty\")\n| stats count by tier",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_top_bar": {
			"name": "Top 15 rooms by utilization",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM\n| rename \"spaceOccupancy.space.name\" as room,\n \"spaceOccupancy.space.capacity\" as capacity,\n \"spaceOccupancy.peakPeopleCount\" as people,\n \"spaceOccupancy.peoplePresence\" as presence,\n \"spaceOccupancy.location.name\" as floor,\n \"spaceOccupancy.location.parent.name\" as building\n| stats avg(people) as avg_people, max(people) as peak by room, capacity\n| eval util=if(capacity>0, round(avg_people/capacity*100, 2), 0)\n| sort - util\n| head 15\n| eval avg_people=round(avg_people, 1)\n| table room, avg_people, peak, util\n| rename room as \"Room\", avg_people as \"Avg People\", peak as \"Peak\", util as \"Util %\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_util": {
			"name": "Room utilization detail",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM\n| rename \"spaceOccupancy.space.name\" as room,\n \"spaceOccupancy.space.capacity\" as capacity,\n \"spaceOccupancy.peakPeopleCount\" as people,\n \"spaceOccupancy.peoplePresence\" as presence,\n \"spaceOccupancy.location.name\" as floor,\n \"spaceOccupancy.location.parent.name\" as building\n| eval occupied=if(presence=\"true\" OR people>0, 1, 0),\n pct=if(capacity>0, round(people/capacity*100, 2), 0)\n| stats avg(pct) as \"Avg Util %\",\n max(pct) as \"Peak Util %\",\n avg(occupied) as occ_rate,\n latest(capacity) as Capacity,\n count as Reports by building, floor, room\n| eval \"Time Occupied %\"=round(occ_rate*100, 2),\n \"Avg Util %\"=round('Avg Util %', 2),\n \"Peak Util %\"=round('Peak Util %', 2)\n| fields building, floor, room, Capacity, \"Avg Util %\", \"Peak Util %\", \"Time Occupied %\", Reports\n| rename building as Building, floor as Floor, room as Room\n| sort Building, Floor, Room",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sankey_flow": {
			"name": "Inter-campus device flow",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| rename devicePresence.device.macAddress as mac\n| eval bldg_self=if(mvfind('devicePresence.location.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.name', null())\n| eval bldg_parent=if(mvfind('devicePresence.location.parent.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.parent.name', null())\n| eval bldg_grand=if(mvfind('devicePresence.location.parent.parent.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.parent.parent.name', null())\n| eval building=coalesce(bldg_self, bldg_parent, bldg_grand)\n| where isnotnull(mac) AND mac!=\"\" AND isnotnull(building) AND building!=\"\"\n| sort mac, _time\n| streamstats current=f last(building) as prev_building by mac\n| where isnotnull(prev_building) AND building!=prev_building\n| stats count by prev_building, building\n| rename prev_building as source, building as target, count as value\n| sort - value\n| head 20",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
