		"ds_user_count_city": {
			"name": "Users by city over time",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'\n| where isnotnull(users) AND isnotnull(city)\n| bin _time span=1h \n| stats max(users) as peak by _time, city\n| stats max(peak) as \"Peak Users\" by city\n| sort - \"Peak Users\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_visitor_daily": {
			"name": "Daily visitors with 7-day forecast",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"\n| eval mac='deviceAssociation.device.macAddress',\n ssid='deviceAssociation.ssid'\n| bin _time span=1d \n| stats dc(mac) as \"Unique Devices\" by _time\n| predict \"Unique Devices\" future_timespan=7",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_visitor_map": {
			"name": "Visitor volume by campus",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=BUILDING\n| eval building='deviceCounts.location.name',\n devices='deviceCounts.deviceCount',\n users='deviceCounts.userCount'\n| stats latest(devices) as devices, latest(users) as visitors by building\n| eval lat=case(match(building, \"(?i)site ?1\"), 0.0,\n match(building, \"(?i)site ?2\"), 1.0,\n 1=1, 0.0),\n lon=case(match(building, \"(?i)site ?1\"), 0.0,\n match(building, \"(?i)site ?2\"), 1.0,\n 1=1, 0.0)\n| where isnotnull(lat)\n| eval devices=round(devices, 2), visitors=round(visitors, 2)\n| rename building as city\n| table city devices visitors lat lon",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_week_compare": {
			"name": "This week vs last week",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| addinfo\n| eval current_start=relative_time(info_max_time, \"-7d@h\"), previous_start=relative_time(info_max_time, \"-14d@h\")\n| where _time>=previous_start AND _time<info_max_time\n| eval users=coalesce('deviceCounts.userCount', 'deviceCounts.associatedCount', 'deviceCounts.deviceCount'),\n floor='deviceCounts.location.name'\n| where isnotnull(users)\n| bin _time span=1h\n| stats max(users) as peak by _time, floor\n| eval week=if(_time>=current_start, \"This Week\", \"Last Week\")\n| stats avg(peak) as avg_peak_users by week\n| append [ | makeresults count=2 | streamstats count | eval week=if(count=1, \"Last Week\", \"This Week\"), avg_peak_users=0 | fields week avg_peak_users ]\n| stats max(avg_peak_users) as \"Avg Peak Users\" by week\n| eval \"Avg Peak Users\"=round('Avg Peak Users', 0)",
				"queryParameters": {
					"earliest": "-14d@h",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wifi_with_occupancy": {
			"name": "WiFi RSSI and Occupancy overlay",
			"options": {
				"query": "`index_catalyst` OR `index_spaces` (sourcetype=\"cisco:dnac:client\" connectionStatus=\"connected\") OR (sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR)\n| eval metric=case(sourcetype=\"cisco:dnac:client\", \"wifi\",\n sourcetype=\"cisco:spaces:firehose\", \"occupancy\"),\n rssi=if(metric=\"wifi\", 'connection.rssi', null()),\n users=if(metric=\"occupancy\", 'deviceCounts.userCount', null())\n| where (metric=\"wifi\" AND isnotnull(rssi) AND rssi<0) OR metric=\"occupancy\"\n| bin _time span=1h \n| stats avg(rssi) as rssi_avg, max(users) as Occupancy by _time\n| eval \"Avg RSSI (dBm)\"=round(rssi_avg, 2),\n Occupancy=round(Occupancy, 2)\n| fields _time \"Avg RSSI (dBm)\" Occupancy",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
